import{bV as e,aL as t,u as n,G as a}from"./chunks/framework.DT-LCgF3.js";const u=JSON.parse('{"title":"拆解 DeepSeek Harness：把 Agent 拆成一棵可替换的插件树","description":"","frontmatter":{"date":"2026-11-26T18:00:00.000Z","title":"拆解 DeepSeek Harness：把 Agent 拆成一棵可替换的插件树","permalink":"/pages/zcode02","categories":["AI","Agent设计模式"]},"headers":[],"relativePath":"AI/13.Agent设计模式/拆解DeepSeekHarness架构.md","filePath":"AI/13.Agent设计模式/拆解DeepSeekHarness架构.md","lastUpdated":1795684220000}'),o={name:"AI/13.Agent设计模式/拆解DeepSeekHarness架构.md"};function p(d,s,r,l,c,i){return t(),n("div",null,[...s[0]||(s[0]=[a(`<h1 id="拆解-deepseek-harness-把-agent-拆成一棵可替换的插件树" tabindex="-1">拆解 DeepSeek Harness：把 Agent 拆成一棵可替换的插件树 <a class="header-anchor" href="#拆解-deepseek-harness-把-agent-拆成一棵可替换的插件树" aria-label="Permalink to &quot;拆解 DeepSeek Harness：把 Agent 拆成一棵可替换的插件树&quot;">​</a></h1><blockquote><p><strong>本文定位</strong></p><p>本文拆解 DeepSeek Harness（下称 DSH）的 Agent 架构。素材来自本地安装的 DSH 发行版<strong>自带官方中文文档</strong>（<code>docs/architecture.zh.md</code>、<code>docs/agent-lifecycle.zh.md</code>、<code>docs/tool-execution-pipeline.zh.md</code>、<code>docs/subsystems/tools.zh.md</code> 等），不是外部推测。</p><p>与 <a href="./拆解ZCode架构实现">拆解 ZCode</a> 的关系：ZCode 用<strong>一份极其严格的规范文档</strong>约束&quot;改工具要走完 12 道关&quot;；DSH 用<strong>插件化架构</strong>让&quot;每个部件都能被替换&quot;。两种思路解决的是同一个问题——<strong>如何让一个 Agent 长期演进而不腐化</strong>——但答案很不一样。</p><p>一点说明：DSH 的文档体系有 <strong>241 篇中文文档</strong>，本文只挑架构主干。想深入某一块，文末给了入口。</p></blockquote><h2 id="一、一句话概括-没有内核的-agent" tabindex="-1">一、一句话概括：没有内核的 Agent <a class="header-anchor" href="#一、一句话概括-没有内核的-agent" aria-label="Permalink to &quot;一、一句话概括：没有内核的 Agent&quot;">​</a></h2><p>DSH 的架构文档开头就给了一个非常明确的立场：</p><blockquote><p><a href="./cordis-primer.zh">Cordis</a> 是 dsh 底层的框架：插件向共享上下文贡献服务、类型化事件和可逆的副作用。<strong>产品的每一部分都是插件，包括模型适配器、工具注册表、会话日志，以及 agent loop（智能体循环）本身</strong>，因此每个都可以从配置替换。</p><p><strong>不存在需要打补丁的特权内核</strong>：扩展 dsh 的方式是把插件挂载到其他插件旁边，而各项注册都是副作用，会在其插件卸载时撤销。</p></blockquote><p>这句话值得反复读。大多数 coding agent 的架构是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐</span></span>
<span class="line"><span>│   固定内核       │  ← 想改这里，只能 fork 或者打补丁</span></span>
<span class="line"><span>│  agent loop     │</span></span>
<span class="line"><span>│  工具执行       │</span></span>
<span class="line"><span>│  会话管理       │</span></span>
<span class="line"><span>└─────────────────┘</span></span>
<span class="line"><span>        ↑</span></span>
<span class="line"><span>   插件只能挂在这里</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>DSH 是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│            Cordis 上下文（ctx）           │</span></span>
<span class="line"><span>│  ┌────────┐ ┌────────┐ ┌────────┐       │</span></span>
<span class="line"><span>│  │agent   │ │tools   │ │sessions│  ...  │</span></span>
<span class="line"><span>│  │loop    │ │        │ │        │       │</span></span>
<span class="line"><span>│  └────────┘ └────────┘ └────────┘       │</span></span>
<span class="line"><span>│       ↑ 全部是插件，全部可替换            │</span></span>
<span class="line"><span>└──────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>连 agent loop 本身都是插件</strong>（<code>ctx.agentLoop</code>）。这是本文所有其他设计的前提。</p><h2 id="二、cordis-的五个概念" tabindex="-1">二、Cordis 的五个概念 <a class="header-anchor" href="#二、cordis-的五个概念" aria-label="Permalink to &quot;二、Cordis 的五个概念&quot;">​</a></h2><p>要理解 DSH，先理解它依赖的框架。<code>docs/cordis-primer.zh.md</code> 把 Cordis 归纳为五条：</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th></tr></thead><tbody><tr><td><strong>插件</strong></td><td>实现 Service 的对象，可带 <code>inject</code> 与 <code>apply(ctx)</code></td></tr><tr><td><strong>上下文</strong></td><td>服务的容器；一个服务占据稳定的 <code>ctx.&lt;key&gt;</code>（如 <code>ctx.tools</code>）</td></tr><tr><td><strong><code>inject</code></strong></td><td>声明依赖；插件等待依赖就绪才启动</td></tr><tr><td><strong>类型化事件</strong></td><td>用 TS 声明合并注册事件名，以五种模式分发</td></tr><tr><td><strong>可逆副作用</strong></td><td>注册通过 <code>ctx.effect()</code> / <code>ctx.on()</code> 安装，卸载时撤销</td></tr></tbody></table><p>第三点特别值得注意：</p><blockquote><p>插件声明所需的服务后，会等待这些服务就绪才启动；<strong>加载顺序通过服务依赖表达，而非手动编排启动序列。</strong></p></blockquote><p>这句话解决的是插件系统的经典难题：<strong>初始化顺序</strong>。你不写 <code>initDatabase(); initTools(); initAgent();</code>，而是声明&quot;我需要 <code>ctx.tools</code>&quot;，框架自己算顺序。</p><h3 id="五种事件分发模式" tabindex="-1">五种事件分发模式 <a class="header-anchor" href="#五种事件分发模式" aria-label="Permalink to &quot;五种事件分发模式&quot;">​</a></h3><p>这是 Cordis 机制里最有设计感的部分：</p><table tabindex="0"><thead><tr><th>模式</th><th>是否 await</th><th>分发顺序</th><th>有返回值</th></tr></thead><tbody><tr><td><code>emit</code></td><td>否</td><td>按注册顺序观察</td><td>否</td></tr><tr><td><code>waterfall</code></td><td>否</td><td>按注册顺序观察</td><td><strong>是</strong></td></tr><tr><td><code>parallel</code></td><td>是</td><td>全部并行</td><td>否</td></tr><tr><td><code>serial</code></td><td>是</td><td>按注册顺序</td><td>是</td></tr><tr><td><code>bail</code></td><td>否</td><td>按注册顺序，碰到 bail 值即停</td><td>是</td></tr></tbody></table><p><code>waterfall</code> 是<strong>环绕中间件</strong>：</p><blockquote><p>监听器接收 <code>(...args, next)</code>。调用 <code>next()</code> 会执行下游监听器；下游返回值通过 <code>next()</code> 返回当前包装层，可由该层包装后继续向外返回。<strong>不调用 <code>next()</code> 直接返回则短路。</strong></p></blockquote><p>配套的设计原则也写清楚了：</p><blockquote><p>对于单决策事件，短路是设计意图。策略监听器在拥有决策权时可以<strong>不调用 <code>next()</code> 直接返回</strong>，而仅做标注或观察的监听器则必须委托。</p></blockquote><p><strong>这两句话合起来定义了一套清晰的责任划分</strong>：有权拒绝的人可以拦断，只做观察的人必须放行。这样权限系统、审计日志、遥测可以挂在同一条链上而不互相干扰。</p><h2 id="三、profile-与组合包-组装的层次" tabindex="-1">三、Profile 与组合包：组装的层次 <a class="header-anchor" href="#三、profile-与组合包-组装的层次" aria-label="Permalink to &quot;三、Profile 与组合包：组装的层次&quot;">​</a></h2><p>DSH 不是&quot;一个配置&quot;，而是<strong>层层叠加出来的插件树</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>起点：空条目列表</span></span>
<span class="line"><span>  ↓ 叠加 profile 中有序的组合包</span></span>
<span class="line"><span>  ↓ 叠加 profile 的 cordis.patch.yml</span></span>
<span class="line"><span>  ↓ 叠加 home patch</span></span>
<span class="line"><span>  ↓ 叠加 --patch overlay</span></span>
<span class="line"><span>最终：运行中的插件树</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>两个核心概念：</p><ul><li><strong>profile</strong> —— 存放在 Harness home 中的具名组装，列出自己叠放的组合包</li><li><strong>组合包（bundle）</strong> —— Cordis 配置项及其挂载代码的分发格式，<strong>插入的内容始终可被其上各层 patch</strong></li></ul><p>随发行版交付的 profile 有五个：<code>web</code>、<code>headless</code>、<code>sdk</code>、<code>sdk-minimal</code>、<code>acp</code>。</p><p>它们的共享基础是 <code>dsh-base</code>：模型适配器、工具、持久化、沙箱与审批策略、设置、凭据、遥测。在此之上：</p><table tabindex="0"><thead><tr><th>profile</th><th>增加什么</th></tr></thead><tbody><tr><td><code>web</code></td><td>浏览器应用（<code>dsh-web-app</code>）</td></tr><tr><td><code>headless</code></td><td>不带服务器的一次性运行器</td></tr><tr><td><code>sdk</code></td><td>SDK JSON-RPC 服务器</td></tr><tr><td><code>acp</code></td><td>仅用于自动化的 ACP 服务器</td></tr><tr><td><code>sdk-minimal</code></td><td><strong>刻意保留的例外</strong>：不应用 <code>dsh-base</code>，拥有完整显式配置树</td></tr></tbody></table><p><strong><code>sdk-minimal</code> 这个例外很说明问题</strong>：架构允许&quot;不按默认路径来&quot;，而不是逼所有人接受同一套基础。</p><p>调试手段也很直接：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>文档说得很硬气：</p><blockquote><p>它打印出的任何条目，都可以由你自己的 patch 替换。</p></blockquote><h2 id="四、核心包与-ctx-键" tabindex="-1">四、核心包与 ctx 键 <a class="header-anchor" href="#四、核心包与-ctx-键" aria-label="Permalink to &quot;四、核心包与 ctx 键&quot;">​</a></h2><p>DSH 的每个核心能力都占一个 <code>ctx</code> 键：</p><table tabindex="0"><thead><tr><th>包</th><th>职责</th><th><code>ctx</code> 键</th></tr></thead><tbody><tr><td><code>core/session</code></td><td>仅追加的 <code>SessionEvent</code> 日志和内存存储</td><td><code>ctx.sessions</code></td></tr><tr><td><code>core/system-prompt</code></td><td>提示词片段与工具 schema 的组装</td><td><code>ctx.systemPrompt</code></td></tr><tr><td><code>core/tools</code></td><td>作用域化的工具注册表和带把关的执行流水线</td><td><code>ctx.tools</code></td></tr><tr><td><code>core/agent</code></td><td><code>Agent</code> 接口、活跃 agent 注册表和 <code>agent/*</code> 事件</td><td><code>ctx.agents</code></td></tr><tr><td><code>core/agent-loop</code></td><td>实现该接口的默认驱动器</td><td><code>ctx.agentLoop</code></td></tr><tr><td><code>core/scope</code></td><td>按 agent 划分作用域的注册原语</td><td>库，无 ctx 键</td></tr><tr><td><code>llm/llm</code></td><td>消息与流式词汇表，以及适配器 seam</td><td><code>ctx.llm</code></td></tr></tbody></table><p>注意 <code>core/agent</code> 和 <code>core/agent-loop</code> 是<strong>分开的两个包</strong>：一个定义接口，一个提供默认实现。这意味着<strong>你可以换掉默认的 loop，而不用改任何调用方</strong>。</p><h2 id="五、能力接缝-seam-替换一个提供方-改变整个产品" tabindex="-1">五、能力接缝（Seam）：替换一个提供方，改变整个产品 <a class="header-anchor" href="#五、能力接缝-seam-替换一个提供方-改变整个产品" aria-label="Permalink to &quot;五、能力接缝（Seam）：替换一个提供方，改变整个产品&quot;">​</a></h2><p>这是 DSH 架构里我认为最有价值的思想。</p><h3 id="什么是-seam" tabindex="-1">什么是 seam <a class="header-anchor" href="#什么是-seam" aria-label="Permalink to &quot;什么是 seam&quot;">​</a></h3><blockquote><p>一个 <strong>seam</strong> 是一项可替换能力，包含三种角色：声明接口的 <strong>Service Definition</strong>、实现它的 <strong>Service Provider</strong>，以及使用它的 <strong>Consumer</strong>（通常是面向模型的工具）。</p><p>一个包可以合并承担多个角色，但<strong>单一角色本身不是 seam</strong>；添加一项能力意味着把三者一并设计。</p></blockquote><h3 id="它带来的效果" tabindex="-1">它带来的效果 <a class="header-anchor" href="#它带来的效果" aria-label="Permalink to &quot;它带来的效果&quot;">​</a></h3><p>文档给了一个极好的例子：</p><blockquote><p>seam 正是替换一个提供方就能改变整个产品的原因。<strong>文件系统与进程提供方共享同一个执行世界</strong>，因此把它们指向远程沙箱，也就把 Bash、PTY 和 LSP 一并搬了过去，无需提供方专用 fork。</p></blockquote><p>这句话点破了很多自研 agent 做远程执行时的痛点：如果你在 Bash 工具内部写死了&quot;用本地 <code>child_process</code>&quot;，那想支持远程沙箱就得改工具；而如果执行能力是一个 seam，<strong>你只换 Provider，所有依赖它的工具自动跟着走</strong>。</p><p>这和前面翻译的 <a href="./用稳定的接口扩展托管智能体">用稳定的接口扩展托管智能体</a> 是同一个思路——那篇讲 Anthropic 怎么把 &quot;大脑&quot; 和 &quot;手&quot; 解耦；DSH 把它落到了插件系统的粒度上。</p><h2 id="六、轮次流程-一个-turn-里发生了什么" tabindex="-1">六、轮次流程：一个 turn 里发生了什么 <a class="header-anchor" href="#六、轮次流程-一个-turn-里发生了什么" aria-label="Permalink to &quot;六、轮次流程：一个 turn 里发生了什么&quot;">​</a></h2><p>DSH 文档用一段伪代码精确描述了循环。这是全文技术密度最高的一段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>turn/start</span></span>
<span class="line"><span>  claim next-step input plus one queued message</span></span>
<span class="line"><span>  snapshot Session model selection; assemble prompt sections + step-admitted tool schemas</span></span>
<span class="line"><span>  -&gt; agent/pre-step; project runtime context at fallback</span></span>
<span class="line"><span>                                     reject | enter(messages, startsRequestSeries?)</span></span>
<span class="line"><span>     reject, or a first enter rewritten empty -&gt; close the turn with no step</span></span>
<span class="line"><span>     step/start</span></span>
<span class="line"><span>     agent/request -&gt; prepareCall (cancellation commits neither system nor users)</span></span>
<span class="line"><span>     reconcile system/message using the prepared call capability</span></span>
<span class="line"><span>     append entered messages as user/message; reconcile retained runtime context</span></span>
<span class="line"><span>     log request/header and request/context as needed</span></span>
<span class="line"><span>     derive and freeze model history from the log</span></span>
<span class="line"><span>     stream the bound prepared call -&gt; llm/stream -&gt; agent/assistant-stream start</span></span>
<span class="line"><span>       agent/assistant-stream chunk*</span></span>
<span class="line"><span>       assistant/message | assistant/attempt -&gt; agent/assistant-stream end</span></span>
<span class="line"><span>     tool/call* -&gt; tools/pre-execute -&gt; tools/execute -&gt; tools/post-execute -&gt; tool/result*</span></span>
<span class="line"><span>     step/end</span></span>
<span class="line"><span>     tools owe another request, or next-step input arrived -&gt; claim -&gt; next step</span></span>
<span class="line"><span>  -&gt; agent/turn-stopping</span></span>
<span class="line"><span>turn/end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><h3 id="术语先说清" tabindex="-1">术语先说清 <a class="header-anchor" href="#术语先说清" aria-label="Permalink to &quot;术语先说清&quot;">​</a></h3><blockquote><p>一个<strong>步骤</strong>是一次模型请求加上它调用的工具。一个<strong>轮次</strong>包含零个或多个步骤：它在领取首条输入之前打开，并在不再欠下任何工作时关闭。</p></blockquote><p><strong>步骤（step）≠ 轮次（turn）</strong>。一轮可能有很多步。这个区分很重要，因为后面所有&quot;该在哪一层拦&quot;的讨论都依赖它。</p><h3 id="三个值得学的细节" tabindex="-1">三个值得学的细节 <a class="header-anchor" href="#三个值得学的细节" aria-label="Permalink to &quot;三个值得学的细节&quot;">​</a></h3><p><strong>① 取消的原子性</strong></p><blockquote><p><code>agent/request -&gt; prepareCall</code>（<strong>取消既不提交 system 也不提交 users</strong>）</p></blockquote><p>如果用户在 prepareCall 期间取消，系统提示词和用户消息都不会被写进日志。这避免了&quot;日志里有半次请求&quot;的脏数据。</p><p><strong>② 重试不重复副作用</strong></p><blockquote><p>重试不重复组装或 <code>agent/pre-step</code>。</p></blockquote><p>重试只是重新发请求，不会重新跑一遍上下文组装、不会重新跑一遍 input 拦截钩子。<strong>副作用必须只发生一次。</strong></p><p><strong>③ 事件分两类</strong></p><blockquote><p><code>turn/*</code>、<code>step/*</code>、<code>system/message</code>、<code>user/message</code>、<code>assistant/message</code>、<code>assistant/attempt</code> 和 <code>tool/*</code> 是<strong>持久会话事件</strong>；其余是分属三个事件域的<strong>实时扩展点</strong>。</p></blockquote><p>这个划分贯穿全篇：</p><ul><li><strong>会话事件</strong>：追加到日志、可回放、重载后仍在 → 用于持久事实</li><li><strong>Agent 事件</strong>（<code>agent/*</code>）：携带活跃 Agent，用于观察或拦截进行中的工作</li><li><strong>能力事件</strong>（<code>fs/*</code>、<code>tools/*</code>、<code>telemetry/*</code>）：不引入循环依赖地附加策略和适配器</li></ul><p><strong>&quot;模型可见即已记录&quot;</strong> 是这条设计的基石：</p><blockquote><p>每个模型请求都必须能从日志重建。新增模型可见输入需要会话事件。</p></blockquote><h2 id="七、会话日志-模型上下文的唯一来源" tabindex="-1">七、会话日志：模型上下文的唯一来源 <a class="header-anchor" href="#七、会话日志-模型上下文的唯一来源" aria-label="Permalink to &quot;七、会话日志：模型上下文的唯一来源&quot;">​</a></h2><blockquote><p>会话日志是模型所见上下文的来源。<code>deriveMessages()</code> 从中投影出模型历史。</p></blockquote><p>这句话的份量在于：<strong>上下文不是&quot;攒&quot;出来的，是&quot;推导&quot;出来的</strong>。你不维护一个 <code>messages[]</code> 数组一路 append，而是从事件日志重新推导。</p><p>好处是 fork、恢复、转录、遥测、持久化<strong>全部从同一份事实派生</strong>，不会出现&quot;内存里的历史和磁盘上的历史不一致&quot;。</p><h3 id="一个真实的失败案例" tabindex="-1">一个真实的失败案例 <a class="header-anchor" href="#一个真实的失败案例" aria-label="Permalink to &quot;一个真实的失败案例&quot;">​</a></h3><p>文档里记录了一条很具体的取舍：</p><blockquote><p>每个 <code>assistant/message</code> 都嵌入产生其组装内容的精确紧凑带时间 stream；<code>assistant/attempt</code> 保留已到达 settlement 的失败、重试、取消与 stream error attempt，且不添加模型历史。</p><p>如果进程在 settlement 前硬中断，则<strong>不会留下持久 attempt stream</strong>。</p></blockquote><p><strong>&quot;进程崩了，没结算的这次尝试就不留痕&quot;</strong> —— 这是有意的：留半条流比不留更危险，因为你无法判断它是否完整。</p><h3 id="格式迁移的严格规则" tabindex="-1">格式迁移的严格规则 <a class="header-anchor" href="#格式迁移的严格规则" aria-label="Permalink to &quot;格式迁移的严格规则&quot;">​</a></h3><blockquote><p>JSONL v0 使用 <code>session.jsonl[.zstd]</code>，v1 及后续版本使用小写 <code>session.vN.jsonl[.zstd]</code>；<strong>已提交 generation 路径绝不重命名、替换或删除</strong>。</p><p>每个相邻迁移包只负责一个 <code>vN -&gt; vN+1</code> 步骤。</p></blockquote><p><strong>只追加、每一代只升一级</strong> —— 这让历史数据永远可读，也让迁移可以逐步验证。</p><h2 id="八、工具定义-模型能看到什么-看不到什么" tabindex="-1">八、工具定义：模型能看到什么，看不到什么 <a class="header-anchor" href="#八、工具定义-模型能看到什么-看不到什么" aria-label="Permalink to &quot;八、工具定义：模型能看到什么，看不到什么&quot;">​</a></h2><p><code>docs/subsystems/tools.zh.md</code> 给出了 <code>ToolDefinition</code> 的完整定义。最关键的是这一句：</p><blockquote><p>注册表的 <code>schemas()</code> 通过<strong>显式允许列表</strong>构建面向模型的 <code>ToolSchema[]</code>；<code>output</code>/<code>execute</code>/<code>projectContent</code>/<code>finalizeContent</code>/<code>timeoutMs</code>/<code>isConcurrencySafe</code>/<code>presentCall</code>/<code>presentResult</code> <strong>绝不能泄漏到模型请求中</strong>。</p></blockquote><p>这和 <a href="./拆解ZCode架构实现">拆解 ZCode</a> 里那个 <code>execute: undefined</code> 是同一个思想的两种实现：<strong>用白名单，而不是黑名单</strong>。黑名单的漏洞是&quot;漏了一个&quot;，白名单的漏洞是&quot;忘了一个&quot;——后者的失败方式是能力变弱，前者的失败方式是泄漏内部实现。</p><h3 id="四个回调的职责边界" tabindex="-1">四个回调的职责边界 <a class="header-anchor" href="#四个回调的职责边界" aria-label="Permalink to &quot;四个回调的职责边界&quot;">​</a></h3><p><code>ToolDefinition</code> 把&quot;结果处理&quot;拆成了四个阶段，边界划得非常清楚：</p><table tabindex="0"><thead><tr><th>回调</th><th>时机</th><th>约束</th></tr></thead><tbody><tr><td><code>output.render</code></td><td>工具返回 JSON 值后</td><td>纯函数，把值投影成 ContentBlock</td></tr><tr><td><code>projectContent</code></td><td><code>tools/post-execute</code> 之前</td><td>安装执行准备好的内容；策略替换仍然权威</td></tr><tr><td><code>finalizeContent</code></td><td><strong>所有</strong>归一化结果（含流水线失败）</td><td><strong>必须 total、不得抛异常</strong></td></tr><tr><td><code>presentCall</code> / <code>presentResult</code></td><td>UI 展示</td><td><strong>纯函数、无副作用</strong>（因为回放时也会调用）</td></tr></tbody></table><p>代码注释里那两句解释特别值得抄下来：</p><blockquote><p>/** 同步的最后一公里转换……该回调必须是 total 的，且不得抛出异常。 */</p></blockquote><blockquote><p>/** 纯函数且无副作用：UI 可能在实时流式<strong>以及</strong>会话日志回放期间调用它，因此它只能依赖 <code>args</code>。 */</p></blockquote><p><strong>第二句是关键</strong>：UI 的展示函数会被回放调用，所以它不能依赖任何运行时状态。如果你在里面读了当前时间、读了全局变量，回放出来的界面就和当时看到的不一样了。</p><h3 id="timeoutms-是-合作式预算" tabindex="-1">timeoutMs 是&quot;合作式预算&quot; <a class="header-anchor" href="#timeoutms-是-合作式预算" aria-label="Permalink to &quot;timeoutMs 是&quot;合作式预算&quot;&quot;">​</a></h3><p>这一条定义极有启发：</p><blockquote><p>协作式工具调用超时预算（毫秒）。省略表示无截止时间。由 <code>@deepseek-ai/dsh-tool-call-timeout-policy</code>（一个 <code>tools/execute</code> 包装器）强制执行；<strong>它永远不会发送给模型</strong>——<code>schemas()</code> 只白名单 name/description/parameters。</p><p><strong>声明它就等于承诺：此工具会把 <code>exec.signal</code> 转发给一个可在信号中止时达到静默的合作式实现。</strong></p></blockquote><p>注意最后一句：<strong>写 <code>timeoutMs</code> 不是&quot;设置一个超时&quot;，而是立一个契约</strong>。如果你声明了超时却不转发 signal，那超时机制只是假装有效。</p><p>同一份代码注释里还留了一句很诚实的话：</p><blockquote><p>/** 执行器会通过 around-dispatch 的信号替换保留调用方取消的语义，并且不会放弃这个 promise，但它<strong>无法硬杀同进程代码</strong>。 */</p></blockquote><p><strong>没法硬杀同进程代码</strong> —— 这是 JS 运行时的事实，文档没有掩饰。</p><h3 id="并发安全默认是关闭的" tabindex="-1">并发安全默认是关闭的 <a class="header-anchor" href="#并发安全默认是关闭的" aria-label="Permalink to &quot;并发安全默认是关闭的&quot;">​</a></h3><blockquote><p>/** 与兄弟工具调用重叠的纯同步分类器。<strong>只有 <code>true</code> 才选择加入</strong>；省略、抛异常、非 <code>true</code> 返回以及无效的 <code>defineTool</code> 参数都视为互斥。此元数据永不模型可见。 */</p></blockquote><p>默认互斥、显式开启才并行——<strong>这是并发设计中正确的默认值</strong>。反过来的话，一个新工具作者只要忘了写判断，就会意外并发。</p><h2 id="九、工具执行流水线-策略挂在哪里" tabindex="-1">九、工具执行流水线：策略挂在哪里 <a class="header-anchor" href="#九、工具执行流水线-策略挂在哪里" aria-label="Permalink to &quot;九、工具执行流水线：策略挂在哪里&quot;">​</a></h2><p><code>docs/tool-execution-pipeline.zh.md</code> 用一张流程图展示了完整管线。我把它压成线性的：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型产出 tool-call 块</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[写日志] tool/call            ← 执行之前先落盘</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[UI] 显示 pending 卡片</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>tools/pre-execute 瀑布       ← hooks、权限、沙箱</span></span>
<span class="line"><span>   ├─ deny → 跳过工具体</span></span>
<span class="line"><span>   └─ ask  → ctx.approval 一次性询问</span></span>
<span class="line"><span>              ├─ 允许一次 → 继续</span></span>
<span class="line"><span>              └─ 拒绝/取消/无法回答 → 跳过</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>已注册的单调守卫             ← deny 或弃权；身份受保护</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>tools/execute 瀑布           ← 超时、重试、指标（环绕分发）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>工具 execute() 本体</span></span>
<span class="line"><span>   ├─ fs/write-intent 或 fs/edit-intent（文件工具专属闸门）</span></span>
<span class="line"><span>   └─ 工具自有会话事件（todo/write、fs/observed 等）</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>projectContent               ← 安装执行准备好的内容</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>tools/post-execute 瀑布      ← 接受、阻止、替换、追加上下文</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>归一化                       ← 流水线/结果快照抛错 → isError</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>finalizeContent              ← 最后一公里内容不变式</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[写日志] tools/result        ← 单一面向模型的结果</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>[UI] 显示完成卡片；批次结算后注入 additionalContexts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br></div></div><h3 id="三个设计要点" tabindex="-1">三个设计要点 <a class="header-anchor" href="#三个设计要点" aria-label="Permalink to &quot;三个设计要点&quot;">​</a></h3><p><strong>① 日志先于执行</strong></p><p><code>tool/call</code> 事件在<strong>执行之前</strong>就被记录。这意味着即使工具把进程搞崩了，日志里也知道&quot;它曾经要执行什么&quot;。</p><p><strong>② 策略与工具解耦</strong></p><p>文档的原话：</p><blockquote><p>这样一来，钩子便可跨越不同工具系列，而无需让工具与某个策略服务耦合。</p></blockquote><p>权限、沙箱、审计都挂在 <code>tools/pre-execute</code> 这个瀑布上，工具本体完全不知道它们存在。</p><p><strong>③ 守卫与瀑布的分工</strong></p><p>注意管线里有两个不同的东西：</p><ul><li><code>tools/pre-execute</code> <strong>瀑布</strong>：可以 await、可以询问用户、可以异步</li><li><strong>注册的单调守卫</strong>：同步、只能 deny 或弃权</li></ul><p>为什么分开？因为<strong>守卫需要是不可重排序的</strong>。文档说：</p><blockquote><p><code>ctx.approval</code> 在单调守卫之前处理询问，而<strong>不得重新排序</strong>的所有者策略仍作为已注册的守卫。</p></blockquote><p>问用户可以等（异步），但某些硬策略必须同步执行且顺序固定。</p><h2 id="十、能力事件-不需要循环依赖的扩展点" tabindex="-1">十、能力事件：不需要循环依赖的扩展点 <a class="header-anchor" href="#十、能力事件-不需要循环依赖的扩展点" aria-label="Permalink to &quot;十、能力事件：不需要循环依赖的扩展点&quot;">​</a></h2><p><code>docs/architecture.zh.md</code> 提到三个事件域，其中第三个是：</p><blockquote><p><strong>能力事件</strong>无需导入循环即可向某个 seam（<code>fs/*</code>、<code>tools/*</code>、<code>telemetry/*</code>）附加策略和适配器。</p></blockquote><p>这个设计解决了一个很实际的问题：<strong>工具需要知道文件系统操作发生了什么，但不能 import 文件系统模块</strong>（否则就是循环依赖）。</p><p>用事件的话：<code>tool-fs</code> 监听 <code>fs/*</code> 事件来实现&quot;先读后编辑&quot;检查——</p><blockquote><p>文件系统的先读后编辑检查位于 <code>tool-fs</code> 之下，通过 <code>fs/*</code> 事件实现。</p></blockquote><p><strong>&quot;你必须先读过文件才能编辑它&quot;</strong> 这条规则，不需要编辑器工具和读取工具互相知道对方。</p><h2 id="十一、新行为该放哪-一张归属表" tabindex="-1">十一、新行为该放哪：一张归属表 <a class="header-anchor" href="#十一、新行为该放哪-一张归属表" aria-label="Permalink to &quot;十一、新行为该放哪：一张归属表&quot;">​</a></h2><p>这是我见过的最实用的架构文档设计——DSH 直接给了一张表，回答&quot;想加功能，该挂在哪&quot;：</p><table tabindex="0"><thead><tr><th>目标</th><th>机制</th></tr></thead><tbody><tr><td>添加模型提供方</td><td>在 <code>ctx.llm</code> 上注册其适配器</td></tr><tr><td>添加面向模型的能力</td><td>在 <code>ctx.tools</code> 上注册；其 schema 加入提示词组装</td></tr><tr><td><strong>让某个会话拥有不同的能力集合</strong></td><td>组装一个 agent preset；服务行需 <code>isolate</code> realm</td></tr><tr><td>添加 shell 执行</td><td>注册 <code>ctx.shell</code> 后端</td></tr><tr><td>添加持久化终端执行</td><td>注册 <code>ctx.terminals</code> 后端</td></tr><tr><td>添加用户命令</td><td>在 <code>ctx.commands</code> 上注册；<strong>无需模型轮次</strong>即可分派</td></tr><tr><td>管理后台任务</td><td>在 <code>ctx.jobs</code> 上注册；<code>job_*</code> 工具读取或停止</td></tr><tr><td>限制所启动的进程</td><td>使用 <code>ctx.sandbox</code> 后端；消费方在启动进程前包装 argv</td></tr><tr><td>拦截请求、工具或轮次</td><td>使用相应 <code>agent/*</code> 或 <code>tools/*</code> 事件</td></tr><tr><td>添加模型可见上下文</td><td>调用 <code>agent.inject()</code>；落到下一次获准的请求中</td></tr><tr><td>添加持久会话状态</td><td>扩展 <code>SessionEventMap</code></td></tr><tr><td>将注册项限定到单个 agent</td><td>使用该 agent 的 <code>agent.ctx</code></td></tr></tbody></table><p><strong>这张表的价值在于它消灭了&quot;这个功能该放哪&quot;的争论</strong>。而且它明确写了：</p><blockquote><p>新行为附加到已有文档记录的扩展点。<strong>改动循环本身时，本映射随之更新。</strong></p></blockquote><h2 id="十二、和-zcode-对比-两种收敛路径" tabindex="-1">十二、和 ZCode 对比：两种收敛路径 <a class="header-anchor" href="#十二、和-zcode-对比-两种收敛路径" aria-label="Permalink to &quot;十二、和 ZCode 对比：两种收敛路径&quot;">​</a></h2><p>两篇拆解写下来，可以把两个 harness 的思路放在一起看：</p><table tabindex="0"><thead><tr><th>维度</th><th>ZCode</th><th>DSH</th></tr></thead><tbody><tr><td>约束载体</td><td>一份 29 万字符的<strong>规范文档</strong></td><td><strong>架构本身</strong>（插件 + seam）</td></tr><tr><td>如何防止腐化</td><td>改工具必须走完 12 环节清单</td><td>能力接缝让替换成本恒定</td></tr><tr><td>工具契约</td><td><code>ToolMetadata</code> 声明 + <code>toContracts()</code> 投影</td><td><code>ToolDefinition</code> + <code>schemas()</code> 白名单</td></tr><tr><td>副作用控制</td><td>外部 I/O 全部收敛到 port/adapter</td><td>注册即副作用，卸载即撤销</td></tr><tr><td>扩展方式</td><td>沿既定链路修改</td><td>把插件挂到旁边</td></tr><tr><td>上下文来源</td><td>Session Event → message history</td><td>Session Event → <code>deriveMessages()</code></td></tr><tr><td>循环可替换性</td><td>未强调</td><td><strong>loop 本身是插件</strong></td></tr><tr><td>适合场景</td><td>多端产品、强合规</td><td>可裁剪内核、按需组装</td></tr></tbody></table><p>有意思的是，<strong>两者对&quot;模型能看到什么&quot;给出了完全一致的答案</strong>：</p><ul><li>ZCode：<code>toContracts()</code> 里 <code>execute: undefined</code></li><li>DSH：<code>schemas()</code> 显式白名单，<code>execute</code>/<code>output</code>/<code>timeoutMs</code> 等绝不外泄</li></ul><p><strong>这大概不是巧合，而是&quot;生产级 agent&quot;的必然选择</strong>：一旦模型能看到执行细节，它就会试图利用；而利用执行细节正是提示注入的攻击面。</p><h2 id="十三、如果你要自己动手-能抄走什么" tabindex="-1">十三、如果你要自己动手，能抄走什么 <a class="header-anchor" href="#十三、如果你要自己动手-能抄走什么" aria-label="Permalink to &quot;十三、如果你要自己动手，能抄走什么&quot;">​</a></h2><p>DSH 的架构对一个个人项目来说显然过重（241 篇文档、5 个 profile、Cordis 框架）。但它有几条判断可以直接搬：</p><p><strong>① 把&quot;循环&quot;和&quot;接口&quot;分开</strong></p><p>DSH 把 <code>core/agent</code>（接口）和 <code>core/agent-loop</code>（默认实现）拆成两个包。你哪怕只有 200 行代码，也可以让 <code>run_agent()</code> 是一个函数，而 <code>Agent</code> 是一个 Protocol/Interface。<strong>换实现时不改调用方。</strong></p><p><strong>② 用白名单投影，而不是黑名单过滤</strong></p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 黑名单：哪天加了新字段就泄漏了</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">schema </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {k: v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k, v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tool.items() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">not</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;execute&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;handler&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 白名单：漏了只会让模型少看到一个字段</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">schema </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {k: tool[k] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> k </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;parameters&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>失败的方向不同，后果差很远。</strong></p><p><strong>③ 把&quot;事件&quot;当扩展点，不要靠 import</strong></p><p>想让&quot;必须先读后写&quot;这条规则生效，不需要让写工具知道读工具的存在。定义一个 <code>fs/before-write</code> 事件，谁关心谁监听。</p><p><strong>④ 超时是契约，不是配置</strong></p><p>如果你声明了 <code>timeout=30s</code> 却不把取消信号传给下游，那这 30 秒只是让调用方白等。<strong>要么真能取消，要么别声明。</strong></p><h2 id="十四、三条总结" tabindex="-1">十四、三条总结 <a class="header-anchor" href="#十四、三条总结" aria-label="Permalink to &quot;十四、三条总结&quot;">​</a></h2><p><strong>其一，可替换性是长期可维护的唯一解。</strong> 不是&quot;设计得好看&quot;，而是<strong>替换成本恒定</strong>。DSH 换一个文件系统提供方，Bash/PTY/LSP 全部跟着走——因为它们是同一个 seam 的消费者。</p><p><strong>其二，默认要安全。</strong> 并发默认关闭、<code>schemas()</code> 用白名单、<code>ask</code> 无法回答时默认 deny、迁移只追加不删改。<strong>每一条都把&quot;出错&quot;导向可恢复的方向。</strong></p><p><strong>其三，文档即架构。</strong> ZCode 用文档约束行为，DSH 让文档成为架构的一部分（那张&quot;新行为放哪&quot;的表、<code>--dump-config</code> 能打出所有可替换条目）。<strong>当文档能回答&quot;我该改哪里&quot;，架构才真正可演进。</strong></p><hr><blockquote><p><strong>延伸阅读</strong></p><ul><li>姊妹篇：<a href="./拆解ZCode架构实现">拆解 ZCode：一个生产级 Coding Agent Harness 的架构实现</a></li><li>设计模式层：<a href="./构建高效的AI智能体">构建高效的 AI 智能体</a></li><li>长期运行的服务化：<a href="./用稳定的接口扩展托管智能体">用稳定的接口扩展托管智能体</a></li><li>从零手写最小 agent：<a href="./../12.Agent工程化/Agent工程化六周实战">从能调到能上线</a></li></ul><p><strong>来源说明</strong>：本文引用的架构表述与代码片段，均取自 DSH 发行版自带的中文文档：<code>docs/architecture.zh.md</code>（架构总览与轮次流程）、<code>docs/cordis-primer.zh.md</code>（Cordis 五概念与事件分发模式）、<code>docs/agent-lifecycle.zh.md</code>（轮次/步骤时序）、<code>docs/tool-execution-pipeline.zh.md</code>（工具执行流水线）、<code>docs/subsystems/tools.zh.md</code>（<code>ToolDefinition</code> 完整定义）。文档随发行版附带，实现可能随版本演进。</p></blockquote>`,152)])])}const g=e(o,[["render",p]]);export{u as __pageData,g as default};
